import{_ as r,C as i,o as l,c as d,ag as o,E as s,j as t,a}from"./chunks/framework.D1ek-kcM.js";const b=JSON.parse('{"title":"Managing App Requests","description":"","frontmatter":{},"headers":[],"relativePath":"mobile-app/managing-app-requests.md","filePath":"mobile-app/managing-app-requests.md","lastUpdated":1789560296000}'),p={name:"mobile-app/managing-app-requests.md"};function h(u,e,g,c,m,q){const n=i("ImagePopup");return l(),d("div",null,[e[0]||(e[0]=o('<h1 id="managing-app-requests" tabindex="-1">Managing App Requests <a class="header-anchor" href="#managing-app-requests" aria-label="Permalink to &quot;Managing App Requests&quot;">​</a></h1><p>Every tenant&#39;s app request arrives in one place for the super admin to review, pass to the mobile team, and close out with a download link. This page covers that side of the workflow.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to review a tenant&#39;s app request</li><li>How to read the credentials a tenant supplied</li><li>How to talk to the tenant about a request</li><li>How to deliver the finished app, request a correction, or cancel</li></ul></div><h2 id="viewing-requests" tabindex="-1">Viewing requests <a class="header-anchor" href="#viewing-requests" aria-label="Permalink to &quot;Viewing requests&quot;">​</a></h2><p>Go to <strong>Mobile App Requests → All Requests</strong> to see every request across all tenants, with the tenant name and domain alongside each one. You can <strong>search</strong>, <strong>filter</strong>, and <strong>paginate</strong> to find a request quickly.</p>',5)),s(n,{src:"/images/managing-app-requests/super-app-requests.png",alt:"All app requests"}),e[1]||(e[1]=t("p",null,[a("Click the "),t("strong",null,"View"),a(" (eye) icon on a row to open the full request.")],-1)),s(n,{src:"/images/managing-app-requests/super-request-detail.png",alt:"App request detail"}),e[2]||(e[2]=o('<p>The detail screen shows the app name, platform, application IDs, every generated image, and the credential groups the tenant supplied.</p><h2 id="reading-the-credentials" tabindex="-1">Reading the credentials <a class="header-anchor" href="#reading-the-credentials" aria-label="Permalink to &quot;Reading the credentials&quot;">​</a></h2><p>Credentials are stored encrypted and listed as <strong>Stored</strong>. The mobile team needs them to build the app, so the super admin can read them — but only on request: each group has a <strong>Show</strong> link that reveals the account type, the invitation note and the full details, and a <strong>Hide</strong> link that puts them away again.</p><p>Nothing is revealed by default, so opening a request during a screen share does not put an Apple password on the screen.</p><h2 id="downloading-the-images" tabindex="-1">Downloading the images <a class="header-anchor" href="#downloading-the-images" aria-label="Permalink to &quot;Downloading the images&quot;">​</a></h2><p>Select <strong>Download images (ZIP)</strong> to get everything in one archive, foldered by platform.</p><ul><li><strong>android/</strong> — a <code>splash/</code> folder with 7 sizes, named by their exact pixels, and a <code>logo/</code> folder.</li><li><strong>ios/</strong> — a <code>splash/</code> folder with 8 sizes, named the same way, and a <code>logo/</code> folder.</li><li><strong>README.txt</strong> — the app name, request reference, tenant, and what each folder holds.</li></ul><p>Each platform folder carries its own copy of the logo, so a build team working on one platform has everything in one place.</p><h2 id="step-1-—-send-the-request-to-the-mobile-team" tabindex="-1">Step 1 — Send the request to the mobile team <a class="header-anchor" href="#step-1-—-send-the-request-to-the-mobile-team" aria-label="Permalink to &quot;Step 1 — Send the request to the mobile team&quot;">​</a></h2><p>With the request open, select <strong>Create App Request</strong>. The mobile team&#39;s own request form opens in a new tab, where the build is booked in.</p><p>Everything the team needs is on the request screen itself: <strong>Download images (ZIP)</strong> gives them the artwork, and the credential groups can be revealed as described above.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Credentials are never e-mailed and never leave the panel on their own. Copy them from the request when the team asks, and only then.</p></div><h2 id="step-2-—-deliver-the-app" tabindex="-1">Step 2 — Deliver the app <a class="header-anchor" href="#step-2-—-deliver-the-app" aria-label="Permalink to &quot;Step 2 — Deliver the app&quot;">​</a></h2><p>When the team returns the finished build, paste its URL into <strong>Mark as Completed</strong>, with an optional version.</p><p>A request for one platform asks for one URL. A request covering <strong>both</strong> asks for two, because the builds live at different addresses — an <code>.apk</code> or <code>.aab</code> for Android, an App Store link for iOS.</p>',15)),s(n,{src:"/images/managing-app-requests/super-mark-completed.png",alt:"Mark as Completed form"}),e[3]||(e[3]=t("p",null,[a("Saving records the links, moves the request to "),t("strong",null,"Completed"),a(", and e-mails the tenant. Issuing new links disables any earlier ones.")],-1)),e[4]||(e[4]=t("h2",{id:"requesting-a-correction",tabindex:"-1"},[a("Requesting a correction "),t("a",{class:"header-anchor",href:"#requesting-a-correction","aria-label":'Permalink to "Requesting a correction"'},"​")],-1)),e[5]||(e[5]=t("p",null,"If something the tenant submitted is wrong — a logo that reads badly on white, the wrong bundle ID — you do not have to cancel the whole request.",-1)),s(n,{src:"/images/managing-app-requests/super-details-correction.png",alt:"Request correction on a field"}),e[6]||(e[6]=o('<p>Use <strong>Request a Correction</strong> on the field in question and give a reason. The request <strong>stays Open</strong> and only that one field reopens for the tenant to edit; everything else remains locked. The tenant is e-mailed with your reason.</p><h2 id="canceling-a-request" tabindex="-1">Canceling a request <a class="header-anchor" href="#canceling-a-request" aria-label="Permalink to &quot;Canceling a request&quot;">​</a></h2><p>If the request cannot go ahead at all, use <strong>Cancel</strong> and give a reason. The tenant is e-mailed, and the reason is shown on their copy of the request.</p><p>Canceling also frees the platform, so the tenant can raise a fresh request for it. <strong>Create App Request</strong> disappears from a canceled request — there is no build left to ask for.</p>',4)),s(n,{src:"/images/managing-app-requests/super-request-cancle.png",alt:"Cancle the Request"}),e[7]||(e[7]=t("h2",{id:"talking-to-the-tenant",tabindex:"-1"},[a("Talking to the tenant "),t("a",{class:"header-anchor",href:"#talking-to-the-tenant","aria-label":'Permalink to "Talking to the tenant"'},"​")],-1)),e[8]||(e[8]=t("p",null,[a("Every request carries a "),t("strong",null,"Messages"),a(" thread, shared by the super admin and the tenant. Use it for anything that is not a field correction — a question about an account, a screenshot from the store review, a note about timing.")],-1)),e[9]||(e[9]=t("ul",null,[t("li",null,"Both sides see every message, with who wrote it and when."),t("li",null,"Files can be attached: up to 5 per message, 10 MB each (PNG, JPG, PDF, ZIP, TXT, JSON, CSV, DOC, DOCX, XLS, XLSX)."),t("li",null,"The other side is e-mailed that a message is waiting. Attachments stay in the panel and are never e-mailed."),t("li",null,"The thread closes for new messages once the request is completed or canceled, and stays readable.")],-1)),s(n,{src:"/images/requesting-an-app/message-req.png",alt:"Message"}),e[10]||(e[10]=o('<h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><ul><li><strong>Open</strong> — the tenant has submitted. The form is locked, you can request a correction on individual fields, and the Messages thread is live.</li><li><strong>Completed</strong> — the download links are recorded and the tenant has been e-mailed.</li><li><strong>Canceled</strong> — you stopped it, with a reason the tenant can read.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Every request is scoped to the tenant that raised it. Tenants see only their own requests; the super admin sees them all in one list.</p></div>',3))])}const w=r(p,[["render",h]]);export{b as __pageData,w as default};
